import os,glob,re
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    G={}
    # Find every grid anchor in this file first
    def parse(s):
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\)',s):
            k,h,w=m[1],int(m[2]),int(m[3])
            pos=s.find(k+' (')
            rows=[]
            off=pos
            while len(rows)<h and off<len(s):
                if s[off:off+3]==' 7 ': pass
                elif s[off:off+len(str(h))].startswith(' ') and any(c.isdigit() for c in s[off+1:off+50]):
                    row=[c for c in s[off:].split()[0] if c.isdigit()]
                    if len(row)>=w and k not in G and all(c.isdigit() for c in row):
                        rows.append([int(x) for x in row[:w]])
                off+=1
            if k not in G and len(rows)==h and all(len(r)==w for r in rows):
                G[k]=rows
    parse(t)
    return G
